package store

import (
	"regexp"
	"strings"
)

// Migrations are written once, in SQLite's dialect. TranslateDDL turns them
// into PostgreSQL mechanically; a migration the rules cannot express gets a
// hand-written override through RegisterDialect.
//
// Rules, applied only outside literals and comments, case-insensitively:
//
//   - `INTEGER PRIMARY KEY AUTOINCREMENT` becomes
//     `BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY`.
//   - A bare `id INTEGER PRIMARY KEY` (SQLite's rowid alias used as a
//     generated id) becomes the same identity column. When it is followed by
//     a CHECK (a singleton row such as `CHECK(id=1)`), or the column has any
//     other name (a natural key such as rating_key or user_id that callers
//     always supply), it becomes `BIGINT PRIMARY KEY`.
//   - INTEGER becomes BIGINT, REAL becomes DOUBLE PRECISION and BLOB becomes
//     BYTEA (SQLite integers are 64-bit, reals are doubles).
//
// Everything else - TEXT, CHECK constraints, DEFAULTs, partial and DESC
// indexes, REFERENCES ... ON DELETE CASCADE, ALTER TABLE ADD COLUMN and seed
// INSERTs - is already valid PostgreSQL and passes through unchanged.
func TranslateDDL(sqliteSQL string) string {
	// Match against a copy whose literals, quoted identifiers and comments
	// are masked as identifier-like runs, then edit the original text at the
	// matched positions (which are always inside code).
	mask := []byte(sqliteSQL)
	pos := 0
	for _, seg := range splitSQL(sqliteSQL) {
		if !seg.code {
			for i := pos; i < pos+len(seg.text); i++ {
				mask[i] = 'x'
			}
		}
		pos += len(seg.text)
	}
	masked := string(mask)
	var b strings.Builder
	b.Grow(len(sqliteSQL) + 64)
	last := 0
	for _, m := range reTypeName.FindAllStringIndex(masked, -1) {
		// A column type follows the column name (or AS in a CAST); a bare
		// keyword elsewhere is itself an identifier, e.g. a column named blob.
		col, ok := precedingIdent(sqliteSQL, masked, m[0])
		if !ok {
			continue
		}
		word := strings.ToUpper(strings.Join(strings.Fields(masked[m[0]:m[1]]), " "))
		var repl string
		switch word {
		case "INTEGER PRIMARY KEY AUTOINCREMENT":
			repl = identityPK
		case "INTEGER PRIMARY KEY":
			if strings.EqualFold(col, "id") && !reCheckNext.MatchString(masked[m[1]:]) {
				repl = identityPK
			} else {
				repl = "BIGINT PRIMARY KEY"
			}
		case "INTEGER":
			repl = "BIGINT"
		case "REAL":
			repl = "DOUBLE PRECISION"
		case "BLOB":
			repl = "BYTEA"
		default:
			continue
		}
		b.WriteString(sqliteSQL[last:m[0]])
		b.WriteString(repl)
		last = m[1]
	}
	b.WriteString(sqliteSQL[last:])
	return b.String()
}

const identityPK = "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"

var (
	reTypeName  = regexp.MustCompile(`(?i)\b(?:INTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT|INTEGER\s+PRIMARY\s+KEY|INTEGER|REAL|BLOB)\b`)
	reCheckNext = regexp.MustCompile(`(?i)^\s*CHECK\b`)
)

// precedingIdent reports the identifier (unquoted, from the original text)
// that precedes position at, separated by whitespace only.
func precedingIdent(orig, masked string, at int) (string, bool) {
	i := at
	for i > 0 && (masked[i-1] == ' ' || masked[i-1] == '\t' || masked[i-1] == '\n' || masked[i-1] == '\r') {
		i--
	}
	if i == at || i == 0 || !isIdentByte(masked[i-1]) {
		return "", false
	}
	end := i
	for i > 0 && isIdentByte(masked[i-1]) {
		i--
	}
	return strings.Trim(orig[i:end], `"`), true
}
